CREATE TABLE IF NOT EXISTS learning_paths (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, level VARCHAR(60) NOT NULL, goals TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS path_courses (path_id VARCHAR(40) NOT NULL, course_id VARCHAR(40) NOT NULL, sort_order INTEGER NOT NULL, PRIMARY KEY(path_id,course_id), UNIQUE(path_id,sort_order), FOREIGN KEY(path_id) REFERENCES learning_paths(id), FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS discussions (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, author_id VARCHAR(40) NOT NULL, parent_id VARCHAR(40), title VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(parent_id) REFERENCES discussions(id));
CREATE TABLE IF NOT EXISTS lesson_notes (user_id VARCHAR(40) NOT NULL, lesson_id VARCHAR(40) NOT NULL, body TEXT NOT NULL, bookmarked INTEGER NOT NULL DEFAULT 0, seconds INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(30) NOT NULL, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(lesson_id) REFERENCES lessons(id));
CREATE TABLE IF NOT EXISTS course_surveys (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, content_rating INTEGER NOT NULL, trainer_rating INTEGER NOT NULL, experience_rating INTEGER NOT NULL, comment TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, UNIQUE(course_id,student_id), FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS discussions_course ON discussions(course_id,parent_id,created_at);
CREATE INDEX IF NOT EXISTS surveys_course ON course_surveys(course_id,created_at);
CREATE INDEX IF NOT EXISTS progress_student ON progress(student_id,lesson_id);
CREATE INDEX IF NOT EXISTS users_role_name ON users(role,name);
CREATE INDEX IF NOT EXISTS enrollments_course_created ON enrollments(course_id,created_at);
